// Two SDKs generated by wabi-wit-gen in ONE JVM: the example (demo:client) and
// the generator's test fixture (demo:greeter). Each brings its own runtime
// (com.demo.client.runtime, com.demo.greeter.runtime) and its own JNI shim
// (libdemo_client_jni, libdemo_greeter_jni), and each core exports its ABI
// under its own symbol prefix. So both can be loaded side by side, through
// Panama and through JNI, without one shadowing the other.
import java.nio.file.Path;

public final class TwoSdks {
    public static void main(String[] args) {
        Path client = Path.of(args[0]);
        Path greeter = Path.of(args[1]);
        int failures = 0;
        for (String binding : new String[] {"panama", "jni"}) {
            var a = com.demo.client.runtime.NativeBackend.load(client, binding);
            var b = com.demo.greeter.runtime.NativeBackend.load(greeter, binding);
            String da = a.description(), db = b.description();
            boolean ok = da.contains("demo:client") && db.contains("demo:greeter")
                    && com.demo.client.runtime.NativeBackend.class != (Class<?>) com.demo.greeter.runtime.NativeBackend.class;
            System.out.println((ok ? "ok    " : "FAIL  ") + binding + ": " + da + " | " + db);
            if (!ok) failures++;
        }
        if (failures > 0) System.exit(1);
    }
}
